game_loop.code:
def run(self):
    while self.running:
        dt = min(self.clock.tick(FPS) / 1000, .05)
        for event in pygame.event.get():
            self.handle_event(event)
        self.update(dt)
        self.draw()
    pygame.quit()

game_input.code:
def handle_event(self, event):
    if event.type == pygame.QUIT:
        self.running = False
    if event.type == pygame.WINDOWFOCUSLOST and self.state == 'playing':
        self.state = 'paused'
        self.selection = 0
    if event.type != pygame.KEYDOWN:
        return
    key = event.key
    if key == pygame.K_m:
        self.audio.enabled = not self.audio.enabled
    if self.state == 'title':
        if key in (pygame.K_RETURN, pygame.K_SPACE):
            self.ai_controller = None
            self.start()
        elif key == pygame.K_i:
            self.watch_ai()
        elif key == pygame.K_ESCAPE:
            self.running = False
    elif self.state == 'playing':
        if key == pygame.K_ESCAPE:
            self.state = 'paused'
            self.selection = 0
            self.audio.play('select')
    elif self.state == 'paused':
        if key == pygame.K_ESCAPE:
            self.state = 'playing'
        elif key in (pygame.K_UP, pygame.K_w, pygame.K_DOWN, pygame.K_s):
            self.selection = (self.selection + (-1 if key in (pygame.K_UP, pygame.K_w) else 1)) % 3
            self.audio.play('select')
        elif key == pygame.K_r:
            self.start()
        elif key in (pygame.K_RETURN, pygame.K_SPACE):
            if self.selection == 0:
                self.state = 'playing'
            elif self.selection == 1:
                self.start()
            else:
                self.running = False
    elif self.state == 'over':
        if key in (pygame.K_r, pygame.K_RETURN, pygame.K_SPACE):
            self.start()
        elif key == pygame.K_ESCAPE:
            self.state = 'title'
            self.ai_controller = None

particles.code:
def burst(self, x, y, count=50):
    for _ in range(count):
        a = self.rng.uniform(0, math.tau)
        speed = self.rng.uniform(30, 220)
        self.items.append([x, y, math.cos(a) * speed, math.sin(a) * speed,
                           self.rng.uniform(.3, 1), self.rng.choice([CYAN, PINK, GOLD, WHITE])])

env_reset.code:
def reset(self, seed=None):
    if seed is not None:
        self.world.rng.seed(seed)
    self.world.reset()
    self.steps = 0
    self.done = False
    return observe(self.world)

