class QNetwork(nn.Module):
    def __init__(self):
        super().__init__()
        self.layers = nn.Sequential(nn.Linear(STATE_SIZE, 128), nn.ReLU(),
                                    nn.Linear(128, 128), nn.ReLU(), nn.Linear(128, 3))

    def forward(self, state):
        return self.layers(state)

epsilon.code:
def epsilon(self, step):
    c = self.config
    return c.epsilon_start + (c.epsilon_end-c.epsilon_start) * min(1, step/c.epsilon_decay_steps)

act.code:
def act(self, state, epsilon=0):
    if epsilon and self.rng.random() < epsilon:
        return int(self.rng.integers(3))
    with torch.no_grad():
        return int(self.online(torch.from_numpy(state)).argmax().item())

replay_sample.code:
def sample(self, batch_size):
    if self.size < batch_size:
        raise ValueError('Not enough transitions for a batch.')
    indices = self.rng.choice(self.size, batch_size, replace=False)
    return tuple(torch.from_numpy(values[indices]) for values in
                 (self.states, self.actions, self.rewards, self.next_states, self.terminals))
